class UcUe(LteUe):
    """Uc Ue class provides ue control via ultracaller."""

    def __init__(self, name, configuration=None):
        """
        Definition of Abstract UE API
        :param name: name of UE to be stored inside UE object
        """
        super(UcUe, self).__init__(name, configuration)

        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {'area': 'UE', 'ue_id': self.get_imei()})
        self.logger.info('"{}" instance of UcUe created: '.format(name))

        self._uc_connection = self._configuration['uc_connection']
        self.ue_alive_timeout = self._configuration['ue_alive_timeout']

        self.ne_id = UeIdentification(identifiers=[('ultracaller', self.get_imei())], network_elem_type='UE',
                                      specific_for_tool='ultracaller')

    @property
    def id(self):
        """
        Return ue id specific for used ue-implementation/tool.

        :return: tool specific ue id
        """
        return self.get_imei()

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Basic <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def attach(self, timeout=-1):
        """
        Not real attach. Checks that UE is alive and connected to network.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        """
        self._refresh_ue_info()
        self._is_ue_alive(self._configuration['ue_info'], 60)
        self._is_ue_connected(self._configuration['ue_info'])

    def detach(self, timeout=-1):
        """
        Not real detach. Stops all running tests.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If detach failed
        """
        self._refresh_ue_info()
        if not self._is_idle():
            self.logger.warning('Ue {} detached while running tests. Stopping running tests.'.format(self.name))
            self._uc_connection.stop_all(self.get_imei())

    def shutdown(self):
        """
        Shutdown stops running tests and unassigns assigned tests from ue.

        :return: None
        """
        self._uc_connection.stop_all(self.get_imei())
        self._uc_connection.unassign_all_tests(self.get_imei())

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Voice/Data Transfer <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def _create_data_transfer(self, name, dt_definition):
        """
        Method for creating Ultracaller data transfer.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: data_transfer - object derivered from lte_data_transfer class
        """
        if dt_definition.protocol == 'ftp':
            return UcFtp(name=name, dt_definition=dt_definition,
                         configuration=self._configuration, uc_connection=self._uc_connection,
                         logger_name=self.ue_logger_name)

        if dt_definition.protocol == 'icmp':
            return UcIcmp(name=name, dt_definition=dt_definition,
                          configuration=self._configuration, uc_connection=self._uc_connection,
                          logger_name=self.ue_logger_name)

        if not self._configuration.get('APP_SERVERS') and \
                (dt_definition.protocol == 'tcp' or dt_definition.protocol == 'udp'):
            return UcTcpProfile(name=name, dt_definition=dt_definition,
                                configuration=self._configuration, uc_connection=self._uc_connection,
                                logger_name=self.ue_logger_name)

        if dt_definition.protocol in ['tcp', 'udp'] \
                and self._configuration.get('APP_SERVERS') and dt_definition.direction in ['ul', 'dl']:
            if not dt_definition.protocol_details.get('ue_ip'):
                dt_definition.protocol_details['ue_ip'] = self.get_info(info_type='IP')
            return UcIperf(name=name, dt_definition=dt_definition,
                           configuration=self._configuration, uc_connection=self._uc_connection,
                           logger_name=self.ue_logger_name)

        raise UltraCallerNotSupportedProtocol(
            'Protocol {} not supported with direction {}'.format(dt_definition.protocol, dt_definition.direction))

    def _create_voice_call(self, name, definition):
        """
        Method for creating Ultracaller voice call.

        :param name: name to be assigned to voice call. You must use it later on to reference given voice call.
        :param definition: object of VoiceCallDefinition that encapsulates all needed parameters.
        :return: voice_call - object derivered from VoiceCall class
        """
        return UcVoiceCall(name=name, ue_name=self.name, definition=definition,
                           imei=self._configuration['imei'], uc_connection=self._uc_connection,
                           logger_name=self.ue_logger_name)

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> SMS <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def send_sms(self, destination, text):
        """
        Send SMS to given number with given text.

        :param destination: destination UE number
        :param text: Message that will be send to UE
        :return: None
        """
        test_name = 'sms_{}'.format(''.join(
            random.choice(string.ascii_uppercase + string.digits) for _ in range(5)))
        params = {"phoneNumber": destination, "text": text}
        self._uc_connection.new_test(test_name=test_name, test_type='Short message', test_params=params)

        try:
            # Start created test
            response = self._uc_connection.start_test(self.get_imei(), test_name)
            test_id = response['data']['testId']

            phase = self._uc_connection.wait_until_test_phase(test_id=test_id, phase=UcPhase.COMPLETED)
            if phase != UcPhase.COMPLETED:
                self.logger.debug('Sending SMS failed')
                raise UltraCallerTestPhaseException('completed')
        finally:
            self._uc_connection.delete_test(test_name=test_name)

    def receive_sms(self, expected_number, expected_text, timeout):
        """
        Check SMS captured by mobile app.

        :param expected_number: Source UE phone number
        :param expected_text: Message that will be received from UE
        :param timeout: Waiting time for message
        :return: None
        """
        raise NotImplementedError()

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Airplane mode <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def enable_airplane_mode(self, duration=None):
        """
        Enable airplane mode

        :param duration: Duration in seconds
        :return None
        :raises UltraCallerCommandFailedException if activation failed
        """
        if not duration:
            duration = 0
        self._uc_connection.airplane_mode(imei=self.get_imei(), duration=duration)

    def disable_airplane_mode(self):
        """
        Disable airplane mode

        :return: None
        :raises UltraCallerCommandFailedException if deactivation failed
        """
        self._uc_connection.airplane_mode(imei=self.get_imei(), duration=-1)

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Mobile Data <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def disable_mobile_data(self, duration=None):
        """
        Disable mobile data

        :param duration: Duration in seconds
        :return: None
        :raises UltraCallerCommandFailedException if deactivation failed
        """
        if not duration:
            duration = 0
        self._uc_connection.mobile_data(imei=self.get_imei(), duration=duration)

    def enable_mobile_data(self):
        """
        Enable mobile data

        :return: None
        :raises UltraCallerCommandFailedException if activation failed
        """
        self._uc_connection.mobile_data(imei=self.get_imei(), duration=-1)

