    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Network mode <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def change_network_mode(self, network_mode):
        """
        Change network mode of UE. Not sure all UEs support this method.
        See:
        https://confluence.int.net.nokia.com/display/LTETPWIKI/ute_ue+keywords+behavior+on+Android#ute_uekeywordsbehavioronAndroid-Changenetworkmodekeyword

        :param network_mode: string inside tuple, see UeManagerProtocol.network_mode_nums2names,
            - LTE only
            - LTE preferred
            - LTE WCDMA
            - WCDMA only
            - WCDMA preferred
            - GSM only
            - GSM UMTS
        """
        # Create test
        test_name = 'network_mode_{}'.format(''.join(
            random.choice(string.ascii_uppercase + string.digits) for _ in range(5)))
        params = {"networkMode": UcUe._format_network_mode_to_uc_format(
            network_mode[0])}  # Note that network mode parameter is tuple
        self._uc_connection.new_test(test_name=test_name, test_type='Network mode', test_params=params)

        try:
            # Start created test
            response = self._uc_connection.start_test(self.get_imei(), test_name)
            test_id = response['data']['testId']

            if not self._uc_connection.wait_until_test_phase(test_id=test_id, phase='completed'):
                self.logger.debug('Network mode FAILED to change within time limit')
                raise UltraCallerTestPhaseException('completed')
        finally:
            self._uc_connection.delete_test(test_name=test_name)

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> UltraCaller Test <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def start_uc_test(self, test_name):
        """
        Start existing UltraCaller test
        :param test_name: Test name
        :return: UcTest
        """
        test_info = self._uc_connection.get_test_info(test_name)
        if not test_info['data']:
            raise ValueError('No test {} found'.format(test_name))

        # This dt is just placeholder which is ignored but framework requires it
        dt = DataTransferDefinition('dl')
        if test_info['data']['type'] == 'TCP profile':
            uc_test = UcTcpProfile(test_name, dt, configuration=self._configuration, uc_connection=self._uc_connection,
                                   logger_name=self.ue_logger_name, test_name=test_name)
        elif test_info['data']['type'] == 'FTP':
            uc_test = UcFtp(test_name, dt, configuration=self._configuration, uc_connection=self._uc_connection,
                            logger_name=self.ue_logger_name, test_name=test_name)
        elif test_info['data']['type'] == 'ICMP ping':
            uc_test = UcIcmp(name=test_name, dt_definition=dt, configuration=self._configuration,
                             uc_connection=self._uc_connection, logger_name=self.ue_logger_name, test_name=test_name)
        else:
            raise UltraCallerNotSupportedTestType('Not supported test type {}'.format(test_info['data']['type']))
        uc_test.start()
        return uc_test

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> UltraCaller Test Sequence <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def start_uc_test_sequence(self, test_sequence_name):
        """
        Start existing UltraCaller test sequence
        :param test_sequence_name:
        :return:
        """
        uc_test_sequence = UcTestSequence(test_sequence_name, self._configuration, self._uc_connection)
        uc_test_sequence.start()
        return uc_test_sequence

    # <=><=><=><=><=><=><=><=><=><=><=><=><=><=> Helper Functions <=><=><=><=><=><=><=><=><=><=><=><=><=><=>
    def get_imei(self):
        """
        Return imei of UE. UcUe:s are identified by using imei.

        :return: String
        """
        return self._configuration['imei']

    def get_info(self, info_type, timeout=None):
        """
        Return information about UE and also log this info.

        :param info_type: string, one of values ['AIRPLANE_MODE', 'APP_VERSION', 'BAT_INFO', 'BAT_LEVEL',
            'BAT_TEMPERATURE', 'CALL_ON', 'IP', 'CLIENT_NAME', 'DEVICE_ID', 'DEVICE_MANU', 'DEVICE_MODEL', 'IMEI',
            'IMSI', 'MOBILE_DATA', 'ROOTED', 'SCREEN_ON', 'STATUS', 'SYSTEM_APP', 'TPUT_DL', 'TPUT_UL', 'UE_OS_VER',
            'USB_STATUS', 'GPS_ON', 'ASU', 'CELL_ID', 'CQI', 'ENBID', 'EARFCN', 'MCC', 'MNC', 'NW_TYPE', 'PCI', 'RSRP',
            'RSRQ', 'SINR', 'SIGNAL_STRENGTH', 'TAC']
        :param timeout: not used
        :return: string with got info or None
        """
        info_dict = {}
        info = self._uc_connection.get_device_info(self.get_imei())

        try:
            data = info.get('data')[0]
        except AttributeError:
            return None
        except TypeError:
            return None

        info_dict['AIRPLANE_MODE'] = UcUe._parse_dictionary(data, 'airplaneMode')
        info_dict['APP_VERSION'] = UcUe._parse_dictionary(data, 'appVer')
        info_dict['BAT_INFO'] = UcUe._parse_dictionary(data, 'batInfo')
        info_dict['BAT_LEVEL'] = UcUe._parse_dictionary(data, 'batLevel')
        info_dict['BAT_TEMPERATURE'] = UcUe._parse_dictionary(data, 'batTemp')
        info_dict['CALL_ON'] = UcUe._parse_dictionary(data, 'callOn')
        info_dict['IP'] = UcUe._parse_dictionary(data, 'clientIpAddr')
        info_dict['CLIENT_NAME'] = UcUe._parse_dictionary(data, 'clientName')
        info_dict['DEVICE_ID'] = UcUe._parse_dictionary(data, 'deviceId')
        info_dict['DEVICE_MANU'] = UcUe._parse_dictionary(data, 'deviceManu')
        info_dict['DEVICE_MODEL'] = UcUe._parse_dictionary(data, 'deviceModel')
        info_dict['IMEI'] = UcUe._parse_dictionary(data, 'imei')
        info_dict['IMSI'] = UcUe._parse_dictionary(data, 'imsi')
        info_dict['MOBILE_DATA'] = UcUe._parse_dictionary(data, 'mobileData')
        info_dict['ROOTED'] = UcUe._parse_dictionary(data, 'rooted')
        info_dict['SCREEN_ON'] = UcUe._parse_dictionary(data, 'screenOn')
        info_dict['STATUS'] = UcUe._parse_dictionary(data, 'status')
        info_dict['SYSTEM_APP'] = UcUe._parse_dictionary(data, 'systemApp')
        info_dict['TPUT_DL'] = UcUe._parse_dictionary(data, 'tputDl')
        info_dict['TPUT_UL'] = UcUe._parse_dictionary(data, 'tputUl')
        info_dict['UE_OS_VER'] = UcUe._parse_dictionary(data, 'osVersion')
        info_dict['USB_STATUS'] = UcUe._parse_dictionary(data, 'usbStatus')

        temp_dict = UcUe._parse_dictionary(UcUe._parse_dictionary(data, 'location'), 'gpsLocation')
        info_dict['GPS_ON'] = UcUe._parse_dictionary(temp_dict, 'gpsOn')

        temp_dict = UcUe._parse_dictionary(UcUe._parse_dictionary(data, 'location'), 'signalInfo')
        info_dict['ASU'] = UcUe._parse_dictionary(temp_dict, 'ASU')
        info_dict['CELL_ID'] = UcUe._parse_dictionary(temp_dict, 'CID')
        info_dict['CQI'] = UcUe._parse_dictionary(temp_dict, 'Cqi')
        info_dict['ENBID'] = UcUe._parse_dictionary(temp_dict, 'eNBID')
        info_dict['EARFCN'] = UcUe._parse_dictionary(temp_dict, 'EARFCN')
        info_dict['MCC'] = UcUe._parse_dictionary(temp_dict, 'MCC')
        info_dict['MNC'] = UcUe._parse_dictionary(temp_dict, 'MNC')
        info_dict['NW_TYPE'] = UcUe._parse_dictionary(temp_dict, 'nwType')
        info_dict['PCI'] = UcUe._parse_dictionary(temp_dict, 'Pci')
        info_dict['RSRP'] = UcUe._parse_dictionary(temp_dict, 'rsrp')
        info_dict['RSRQ'] = UcUe._parse_dictionary(temp_dict, 'rsrq')
        info_dict['SINR'] = UcUe._parse_dictionary(temp_dict, 'sinr')
        info_dict['SIGNAL_STRENGTH'] = UcUe._parse_dictionary(temp_dict, 'SS')
        info_dict['TAC'] = UcUe._parse_dictionary(temp_dict, 'tac')

        for key in info_dict:
            if info_dict[key] == '' or info_dict[key] == 'N/A':
                info_dict[key] = None

        for key in ['AIRPLANE_MODE', 'MOBILE_DATA', 'SCREEN_ON', 'SYSTEM_APP', 'USB_STATUS']:
            if info_dict.get(key) == 0:
                info_dict[key] = False
            elif info_dict.get(key) == 1:
                info_dict[key] = True

        return info_dict.get(info_type)

    @staticmethod
    def _parse_dictionary(dictionary, key):
        """
        Returns requested value from dictionary.
        Can handle None values.
        :param dictionary:
        :param key:
        :return:
        """
        if dictionary is None:
            return None
        else:
            return dictionary.get(key)

    def _is_ue_alive(self, ue_info, alive_timeout=None):
        """
        Checks if ue is reported within alive_timeout

        :param ue_info:
        :param alive_timeout: Timeout in seconds
        :return: None
        :raises UeCommunicationError if timeout is exceeded
        """
        if not alive_timeout:
            alive_timeout = self.ue_alive_timeout
        if alive_timeout > time.time() - ue_info['lastSeen'] / 1000:
            return
        else:
            last_poll = time.time() - ue_info['lastSeen'] / 1000
            self.logger.error('UE is not alive, it has been last seen {}s ago by UltraCaller'.format(last_poll))
            raise UeCommunicationError('Ue {} is not alive'.format(self.name))

    def _is_ue_connected(self, ue_info):
        """
        Checks if ue is connected to network
        :param ue_info:
        :return:
        """
        if not ue_info.get('location', None) or not ue_info['location'].get('signalInfo', None) or \
                not ue_info['location']['signalInfo'].get('CID', None):
            self.logger.warning('Attached ue {} is not connected to network'.format(self.name))

    @staticmethod
    def _format_network_mode_to_uc_format(nw_mode):
        """
        Format requested network mode to android format
        :param nw_mode:
        :return:
        """
        network_modes = {'lte only': 'NETWORK_MODE_LTE_ONLY',
                         'lte preferred': 'NETWORK_MODE_LTE_GSM_WCDMA',
                         'wcdma only': 'NETWORK_MODE_WCDMA_ONLY',
                         'wcdma preferred': 'NETWORK_MODE_WCDMA_PREF',
                         'lte wcdma': 'NETWORK_MODE_LTE_WCDMA',
                         'gsm umts': 'NETWORK_MODE_GSM_UMTS',
                         'gsm only': 'NETWORK_MODE_GSM_ONLY'}
        resolved_nw_mode = network_modes.get(nw_mode.lower(), None)
        if not resolved_nw_mode:
            raise UltraCallerInvalidInputException('change_network_mode', nw_mode)
        return resolved_nw_mode

    def _refresh_ue_info(self):
        """
        Fetch fresh ue info from UltraCaller
        :return:
        """
        response = self._uc_connection.search_ues_by_imei(imei=self.get_imei())
        self._configuration['ue_info'] = response['data'][0]

    def _is_idle(self):
        """
        Checks if ue status is idle
        :return: True if yes, False otherwise
        """
        ue_info = self._configuration['ue_info']
        if ue_info['status'] != 'idle':
            return False
        return True

    def reset(self):
        """
        Reset UE (Only available for rooted or USB connected UE's)
        :return: None
        :raises UltraCallerCommandFailedException if reset failed
        """
        self._uc_connection.reset(imei=self.get_imei())
